# -*- coding: utf-8 -*-
from __future__ import annotations

import base64
import py_compile
import re
import sys
from pathlib import Path

WORKER_B64 = """"""


def _replace_worker_literal(source: str, new_worker: str) -> str:
    m = re.search(r'(?m)^WORKER_CODE\s*=\s*(?:[rRuUbBfF]{0,2})?(?P<q>"""|\'\'\')', source)
    if not m:
        raise RuntimeError("V0.8.2 could not locate WORKER_CODE triple-quoted literal")
    quote = m.group("q")
    end = source.find(quote, m.end())
    if end < 0:
        raise RuntimeError("V0.8.2 could not locate end of WORKER_CODE literal")
    if quote in new_worker:
        raise RuntimeError("V0.8.2 worker unexpectedly contains source quote delimiter")
    replacement = f"WORKER_CODE = r{quote}{new_worker}{quote}"
    return source[:m.start()] + replacement + source[end + len(quote):]


def patch(source_root: Path):
    source_root = Path(source_root).resolve()
    main = source_root / "app" / "src" / "main.py"
    speech = source_root / "app" / "src" / "speech_input.py"
    if not main.exists() or not speech.exists():
        raise FileNotFoundError("V0.8.2 expected V0.8.0 source files")

    main_text = main.read_text(encoding="utf-8")
    speech_text = speech.read_text(encoding="utf-8")

    if 'APP_VERSION = "0.8.0"' not in main_text:
        raise RuntimeError("V0.8.2 expected APP_VERSION 0.8.0 base")

    main_text = main_text.replace('APP_VERSION = "0.8.0"', 'APP_VERSION = "0.8.2"', 1)
    main_text = main_text.replace("V0.8.0", "V0.8.2")

    replacements = [
        (r"美丽[\\s，,。.!！？?、]*美丽", r"美丽[\s ，,。.!！？?、]*美丽", "wake regex"),
        (r"^[\\s，,。.!！？?、:：]+", r"^[\s ，,。.!！？?、:：]+", "wake leading-strip regex"),
        (r"\\s+", r"\s+", "speech whitespace regex"),
    ]
    for old, new, label in replacements:
        count = main_text.count(old)
        if count < 1:
            raise RuntimeError(f"V0.8.2 {label} source token missing: {old!r}")
        main_text = main_text.replace(old, new)
        print(f"V0.8.2 patched {label}: {count} occurrence(s)")

    worker = base64.b64decode(WORKER_B64).decode("utf-8")
    # Repair the one-character typo in the embedded worker payload before installation.
    worker = worker.replace("contextib.redirect_stdout", "contextlib.redirect_stdout")
    compile(worker, "speech_worker.py", "exec")
    speech_text = _replace_worker_literal(speech_text, worker)

    if "funasr>=1.3,<2" not in speech_text:
        raise RuntimeError("V0.8.2 expected FunASR range token missing")
    speech_text = speech_text.replace("funasr>=1.3,<2", "funasr==1.4.16", 1)
    speech_text = speech_text.replace("V0.8.0", "V0.8.2")

    main.write_text(main_text, encoding="utf-8")
    speech.write_text(speech_text, encoding="utf-8")

    py_compile.compile(str(main), doraise=True)
    py_compile.compile(str(speech), doraise=True)

    m = main.read_text(encoding="utf-8")
    sp = speech.read_text(encoding="utf-8")
    checks_main = (
        'APP_VERSION = "0.8.2"',
        r"美丽[\s ，,。.!！？?、]*美丽",
        r"^[\s ，,。.!！？?、:：]+",
    )
    for token in checks_main:
        if token not in m:
            raise RuntimeError(f"V0.8.2 main verification failed: {token}")
    for token in (
        "funasr==1.4.16",
        'language="中文"',
        "itn=True",
        "cache={}",
        "[VAD_START]",
        "[VAD_END]",
        "[ASR_RAW]",
        "[ASR_NORMALIZED]",
        "[ASR_EMPTY]",
        "contextlib.redirect_stdout(sys.stderr)",
    ):
        if token not in sp:
            raise RuntimeError(f"V0.8.2 speech verification failed: {token}")

    print("Patched XiaoMeili source to V0.8.2 speech wake-chain repair")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("usage: patch_v082.py <source_root>")
    patch(Path(sys.argv[1]))
